// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address rewardToken) public {
        // Assume reward token has not been added yet
        vm.assume(rewardToken != address(0));
        // Ensure the reward token is not already added (check by calling rewardPeriodFinish)
        try c.rewardPeriodFinish(rewardToken) returns (uint40 periodFinish) {
            // If periodFinish is not 0, token exists => skip
            vm.assume(periodFinish == 0);
        } catch {
            // If it reverts (e.g., uninitialized mapping), assume false so skip
            vm.assume(false);
        }

        // Record block.timestamp before calling addReward
        uint256 beforeTimestamp = block.timestamp;

        // Call addReward
        c.addReward(rewardToken);

        // After addReward, periodFinish must be exactly beforeTimestamp (not extended by DURATION)
        uint40 actualPeriodFinish = c.rewardPeriodFinish(rewardToken);
        assertTrue(actualPeriodFinish == uint40(beforeTimestamp), "periodFinish should equal block.timestamp after addReward");
    }
}

